type Role = 'citizen' | 'responder' | 'organization' | 'command';
type Page = string;
type Urgency = 'LOW' | 'MODERATE' | 'HIGH' | 'CRITICAL';
type RequestStatus = 'TRIAGED' | 'ASSIGNED' | 'EN ROUTE' | 'ON SCENE' | 'COMPLETED' | 'CANCELLED';

type EmergencyRequest = {
  id:string; text:string; incidentType:string; urgency:Urgency; people:number|null;
  needs:string[]; vulnerabilities:string[]; status:RequestStatus; created:string;
  source:'USER-REPORTED'|'SIMULATED'; responder?:string; eta?:number; location:string; photo?:string;
};

type FamilyMember = {id:string; name:string; relation:string; status:'SAFE'|'CHECK-IN PENDING'|'HELP REQUESTED'; updated:string};

type NavItem={id:string;label:string;icon:any};
type NavGroup={label:string;icon:any;items:NavItem[]};
const items=(rows:Array<[string,string,any]>):NavItem[]=>rows.map(([id,label,icon])=>({id:String(id),label:String(label),icon}));
const navByRole:Record<Role,NavGroup> = {
  citizen:{label:'CITIZEN',icon:Home,items:items([
    ['home','Home',Home],['map','Safety Map',Map],['help','Get Help',Siren],['requests','My Requests',ClipboardList],['alerts','Alerts',Bell],['family','My Family',Users],['shelters','Shelters',Home],['resources','Resources',Package],['volunteers','Volunteer Hub',Users],['donations','Donate',HeartPulse],['profile','Profile & Settings',Settings],['mesh','Offline Mesh',WifiOff],['survival','Survival Mode',BatteryLow]
  ])},
  responder:{label:'RESPONDER',icon:Shield,items:items([
    ['dashboard','Dashboard',Command],['assignments','Assignments',ClipboardList],['map','Response Map',Map],['requests','Institution Reports',Siren],['messages','Messages',MessageSquare],['profile','Settings',Settings]
  ])},
  organization:{label:'ORGANIZATION',icon:Building2,items:items([
    ['dashboard','Dashboard',Command],['resources','Resources',Package],['requests','Requests',ClipboardList],['volunteers','Volunteers',Users],['operations','Operations',Truck],['profile','Profile',Settings],['donations','Donations',HeartPulse]
  ])},
  command:{label:'COMMAND',icon:Command,items:items([
    ['command','Command Centre',Command],['map','National Map',Map],['incidents','Incidents',AlertTriangle],['requests','Requests',ClipboardList],
    ['responders','Responders',Shield],['resources','Resources',Package],['shelters','Shelters',Home],['hospitals','Hospitals',HeartPulse],
    ['organizations','Organisations',Building2],['broadcast','Broadcast',Radio],['alerts','Alerts & Escalations',Bell],['simulation','Simulation',CloudRain],
    ['qa','Command Q&A',Bot],['recovery','Recovery',RefreshCw],['missing','Missing Persons',Users],['verification','Verification',CheckCircle2],
    ['intelligence','Intelligence & Analytics',Layers3],['communications','Communications',MessageSquare],['audit','Audit Trail',Database],['evacuation','Evacuation & Safe Routes',Route],['profile','Settings',Settings]
  ])}
};

const localTriage=(text:string)=>{
  const t=text.toLowerCase(); const n=t.match(/\b(\d{1,3})\b/); const people=n?Number(n[1]):null;
  const incidentType=t.includes('flood')?'Flood':t.includes('fire')?'Fire':t.includes('cyclone')?'Cyclone':t.includes('landslide')?'Landslide':t.includes('earthquake')?'Earthquake':t.includes('storm')?'Storm':'Other';
  const needs:string[]=[]; if(/medical|doctor|injur|ambulance|bleeding|unconscious/.test(t)) needs.push('Medical assistance'); if(/water|thirst/.test(t)) needs.push('Water'); if(/food|hungry/.test(t)) needs.push('Food'); if(/rescue|trapped|stuck|evacuat/.test(t)) needs.push('Rescue / evacuation');
  const vulnerabilities:string[]=[]; if(/child|children|kid/.test(t)) vulnerabilities.push('Children'); if(/elderly|old person|senior/.test(t)) vulnerabilities.push('Elderly'); if(/wheelchair|disab/.test(t)) vulnerabilities.push('Person with disability'); if(/pregnan/.test(t)) vulnerabilities.push('Pregnancy');
  let urgency:Urgency='MODERATE'; if(/critical|dying|unconscious|trapped|urgent|life.?threat/.test(t)) urgency='CRITICAL'; else if(/injur|medical|rescue|evacuat/.test(t)) urgency='HIGH';
  return {people,incidentType,needs:needs.length?needs:['General assistance'],vulnerabilities,urgency};
};

function now(){return new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});}
function uid(prefix:string){return `${prefix}-${Math.floor(1000+Math.random()*8999)}`;}

function Splash({onDone}:{onDone:()=>void}){
  useEffect(()=>{const t=window.setTimeout(onDone,4400);return()=>window.clearTimeout(t)},[onDone]);
  return <div className="splashV2"><div className="splashGrid"/><div className="splashGlow"/><div className="splashLogoWrap"><img src="/resqlink-logo.png" alt="ResQLink"/><div className="splashScan"/></div><div className="splashMeta"><span>RESPONSE INTELLIGENCE NETWORK</span><b>INITIALIZING</b></div><div className="splashProgress"><i/><i/><i/></div></div>
}

function LoginPage({onLogin}:{onLogin:(role:Role)=>void}){
  const [selected,setSelected]=useState<Role>('citizen'); const [email,setEmail]=useState(''); const [password,setPassword]=useState(''); const [showPass,setShowPass]=useState(false);
  const roles:[Role,string,string,any][]=[['citizen','Citizen','Report emergencies, receive alerts and stay connected.',Home],['responder','Responder','Manage assignments, navigation and field response.',Shield],['organization','Organisation','Coordinate resources, teams and relief operations.',Building2],['command','Command','Monitor incidents, resources and the complete response network.',Command]];
  return <div className="loginScreen"><div className="loginAtmosphere"><div className="disasterOrb orbFlood"><Waves/></div><div className="disasterOrb orbFire"><Flame/></div><div className="disasterOrb orbRain"><CloudRain/></div><div className="disasterOrb orbQuake"><span>〰</span></div><div className="loginGrid"/></div><div className="loginBrand"><img src="/resqlink-mark.png" alt=""/><div><b>ResQ<span>Link</span></b><small>EMERGENCY INTELLIGENCE NETWORK</small></div></div><main className="loginCard"><div className="loginCopy"><span className="eyebrowV2">SECURE RESPONSE ACCESS</span><h1>Welcome to the<br/><strong>ResQLink Network</strong></h1><p>Choose your operational role to enter the emergency response environment.</p><div className="loginStatus"><i/> All systems operational <span>•</span> Offline-ready</div></div><div className="roleCards">{roles.map(([r,label,desc,Icon])=><button type="button" key={r} className={`roleCard ${selected===r?'selected':''}`} onClick={()=>setSelected(r)}><span className="roleIcon"><Icon size={19}/></span><span><b>{label}</b><small>{desc}</small></span><ChevronRight size={16}/></button>)}</div><form className="loginForm" onSubmit={e=>{e.preventDefault();onLogin(selected)}}><label>ACCESS ID<input value={email} onChange={e=>setEmail(e.target.value)} placeholder="Enter access ID" autoComplete="username"/></label><label>PASSWORD<div className="passwordWrap"><input type={showPass?'text':'password'} value={password} onChange={e=>setPassword(e.target.value)} placeholder="Enter secure password" autoComplete="current-password"/><button type="button" onClick={()=>setShowPass(!showPass)}>{showPass?'HIDE':'SHOW'}</button></div></label><button className="loginSubmit" type="submit"><span>Enter {roles.find(x=>x[0]===selected)?.[1]} Portal</span><ChevronRight size={17}/></button><div className="loginFoot"><span>Protected operational interface</span><span>Demo access • Local session</span></div></form></main><div className="loginBottom"><span>RESQLINK</span><span>REPORT · VERIFY · COORDINATE · RESPOND · RECOVER</span><span>v7.0</span></div></div> }

