  const citizens=[['CIT-2048','Shawn Kuriakose','East Hyderabad','SAFE','2 requests'],['CIT-1981','Aarav Menon','Uppal','ASSISTANCE REQUESTED','1 request'],['CIT-1734','Priya Rao','Amberpet','SHELTERED','4 requests'],['CIT-1652','Rahul Das','Begumpet','CHECK-IN PENDING','1 request']];
